// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0) && newOwner != address(0) && caller != newOwner);
        vm.prank(caller);
        c.transferOwnership(newOwner);
        vm.prank(caller);
        c.owned();
        assertTrue(c.owner() == caller);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0) && newOwner != address(0));
        vm.assume(caller != c.owner());
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));
        assertTrue(!success || c.owner() == address(0));
    }
}
